function findElementsByType(chart: EChartsType, type: string): Displayable[] {
    const result: Displayable[] = [];
    (chart.getZr().storage.getDisplayList(true) as Element[]).forEach(function (el) {
        if (el.type === type) {
            result.push(el as Displayable);
        }
    });
    return result;
