describe('bar_view', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    describe('large', function () {

        it('borderColor should not hide the bar color', function () {
            chart.setOption({
                xAxis: {
                    data: ['a', 'b', 'c', 'd']
                },
                yAxis: {},
                series: [{
                    type: 'bar',
                    large: true,
                    largeThreshold: 1,
                    data: [1, 2, 3, 4],
                    itemStyle: {
                        color: 'blue',
                        borderColor: 'red',
                        borderWidth: 2
                    }
                }]
            }, true);

            const largeEls = findElementsByType(chart, 'largeBar');
            expect(largeEls.length).toBe(1);
            // Bar color should be kept.
            expect(largeEls[0].style.fill).toBe('blue');
            // The stroke should not cover the fill of the thin bars.
            expect(largeEls[0].style.stroke).toBeFalsy();
        });

        it('should keep the palette color when only borderColor is specified', function () {
            chart.setOption({
                color: ['#123456'],
                xAxis: {
                    data: ['a', 'b', 'c', 'd']
                },
                yAxis: {},
                series: [{
                    type: 'bar',
                    large: true,
                    largeThreshold: 1,
                    data: [1, 2, 3, 4],
                    itemStyle: {
                        borderColor: 'red'
                    }
                }]
            }, true);

            const largeEls = findElementsByType(chart, 'largeBar');
            expect(largeEls.length).toBe(1);
            expect(largeEls[0].style.fill).toBe('#123456');
            expect(largeEls[0].style.stroke).toBeFalsy();
        });

        it('should not affect the normal bar rendering', function () {
            chart.setOption({
                xAxis: {
                    data: ['a', 'b', 'c', 'd']
                },
                yAxis: {},
                series: [{
                    type: 'bar',
                    data: [1, 2, 3, 4],
                    itemStyle: {
                        color: 'blue',
                        borderColor: 'red',
                        borderWidth: 2
                    }
                }]
            }, true);

            const rects = findElementsByType(chart, 'rect');
            expect(rects.length).toBe(4);
            rects.forEach(function (rect) {
                expect(rect.style.fill).toBe('blue');
                expect(rect.style.stroke).toBe('red');
            });
        });

    });

});

