    describe('zero_value_symbol_axes', function () {

        function makeOption(isHorizontalBar: boolean, inverse: boolean, symbol: string) {
            const valueAxis = {
                type: 'value' as const,
                inverse: inverse
            };
            const categoryAxis = {
                type: 'category' as const,
                data: ['A', 'B', 'C']
            };
            return {
                animation: false,
                xAxis: isHorizontalBar ? valueAxis : categoryAxis,
                yAxis: isHorizontalBar ? categoryAxis : valueAxis,
                series: [{
                    type: 'pictorialBar' as const,
                    symbol: symbol,
                    symbolSize: 40,
                    symbolPatternSize: 2,
                    data: [0, 100, -100]
                }]
            };
        }

        const cases = [
            {desc: 'horizontal', isHorizontalBar: true, inverse: false},
            {desc: 'horizontal with inverse axis', isHorizontalBar: true, inverse: true},
            {desc: 'vertical', isHorizontalBar: false, inverse: false},
            {desc: 'vertical with inverse axis', isHorizontalBar: false, inverse: true}
        ];

        const symbols = [
            {desc: 'path symbol', symbol: PATH_SYMBOL},
            {desc: 'image symbol', symbol: IMAGE_SYMBOL}
        ];

        symbols.forEach(function (symbolCase) {
            cases.forEach(function (axisCase) {
                it(
                    'zero value should keep the direction of positive values: '
                        + axisCase.desc + ', ' + symbolCase.desc,
                    function () {
                        chart.setOption(makeOption(
                            axisCase.isHorizontalBar, axisCase.inverse, symbolCase.symbol
                        ), true);

                        // The sign that expresses the direction is on the value dimension.
                        const valueDimIdx = axisCase.isHorizontalBar ? 0 : 1;
                        const zero = getMainSymbolScale(chart, 0)[valueDimIdx];
                        const positive = getMainSymbolScale(chart, 1)[valueDimIdx];
                        const negative = getMainSymbolScale(chart, 2)[valueDimIdx];

                        expect(sign(positive)).not.toBe(0);
                        // Zero is not flipped: it follows the axis direction like positive values.
                        expect(sign(zero)).toBe(sign(positive));
                        // Negative values keep being flipped.
                        expect(sign(negative)).toBe(-sign(positive));
                    }
                );
            });
        });

    });

});

