function getMainSymbolScale(chart: EChartsType, dataIndex: number): number[] {
    const seriesModel = chart.getModel().getSeriesByIndex(0);
    const el = seriesModel.getData().getItemGraphicEl(dataIndex) as any;
    const mainPath = el.__pictorialMainPath;
    return [mainPath.scaleX, mainPath.scaleY];
}

function sign(val: number): number {
    return val > 0 ? 1 : val < 0 ? -1 : 0;
}

